"""Visualize scores regenerated by the saved-model inference pipeline."""
from pathlib import Path
import numpy as np
import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

ROOT=Path(__file__).resolve().parents[1]
def main():
    s=pd.read_csv(ROOT/'results/forward_only_scores.csv')
    out=ROOT/'figures';out.mkdir(exist_ok=True)
    a=s[(s.family=='architecture')&(s.metric=='rmse')]
    fig,ax=plt.subplots(figsize=(9,4.5))
    ax.bar(np.arange(len(a)),a.value,color='#008e7e')
    ax.set_xticks(np.arange(len(a)),a.model,rotation=32,ha='right')
    ax.set_ylabel('Weighted calibration-fit RMSE')
    ax.set_title('PSO–ANN architectures | saved-model scores')
    ax.grid(axis='y',alpha=.15);fig.tight_layout()
    fig.savefig(out/'architecture_scores.png',dpi=160);plt.close(fig)
    r=s[(s.family=='regression')&(s.metric=='rmse')]
    fig,ax=plt.subplots(figsize=(9,4.5))
    ax.barh(np.arange(len(r)),r.value,color='#236e85')
    ax.set_yticks(np.arange(len(r)),r.model)
    ax.invert_yaxis();ax.set_xlabel('Model-specific weighted RMSE')
    ax.set_title('Regression calibrators | saved-model scores')
    ax.grid(axis='x',alpha=.15);fig.tight_layout()
    fig.savefig(out/'regression_scores.png',dpi=160);plt.close(fig)
    print('Generated two saved-model score figures.')
if __name__=='__main__': main()
